#!/usr/bin/env python3
"""Exercise the production server payload producer with actual Vapor streaming."""
import pathlib, subprocess, tempfile, json
repo=pathlib.Path(__file__).resolve().parents[2]
s=(repo/'Aether/Backend/Server/ServerInstaller.swift').read_text()
a=s.index('nonisolated private func _streamPayload(');b=s.index('\n\tprivate func _shutdownServer',a)
header='import Foundation\nimport Vapor\nfinal class Model: @unchecked Sendable {enum Status {case sendingPayload,installing;case broken(Error)};var status=Status.sendingPayload;var uploadProgress=0.0}\nfinal class ServerInstaller: @unchecked Sendable {let viewModel=Model();func _updateStatus(_ status: Model.Status){DispatchQueue.main.async { self.viewModel.status=status }}\n'
main='@main struct Checks {\n @MainActor static func main() async throws {\n  let app = try await Application.make(.testing)\n  let installer=ServerInstaller()\n  let url=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)\n  let bytes=Data((0..<300_000).map {UInt8($0%251)})\n  try bytes.write(to:url)\n  defer {try? FileManager.default.removeItem(at:url)}\n  for (range, expected) in [(nil,bytes),("bytes=123-456",bytes.subdata(in:123..<457)),("bytes=-100",bytes.suffix(100))] as [(String?,Data)] {\n   installer.viewModel.status = .sendingPayload;installer.viewModel.uploadProgress=0\n   var headers=HTTPHeaders();if let range {headers.add(name:.range,value:range)}\n   let request=Request(application:app,method:.GET,url:"/payload.ipa",headers:headers,on:app.eventLoopGroup.next())\n   let response=installer._streamPayload(at:url,for:request)\n   if range != nil {precondition(response.status == .partialContent)}\n   let result=try await response.body.collect(on:request.eventLoop).get()\n   precondition(Data(result!.readableBytesView)==expected,"Streaming preserved range bytes")\n   try await Task.sleep(nanoseconds:10_000_000)\n   precondition(installer.viewModel.uploadProgress == 1)\n   if case .installing=installer.viewModel.status {} else {preconditionFailure("Successful response must advance to installation")}\n  }\n  let cacheRequest=Request(application:app,method:.GET,url:"/cached",on:app.eventLoopGroup.next())\n  let cached=installer._streamPayload(at:url,for:cacheRequest)\n  var cacheHeaders=HTTPHeaders();cacheHeaders.add(name:.ifNoneMatch,value:cached.headers.first(name:.eTag)!)\n  let unchanged=Request(application:app,method:.GET,url:"/cached",headers:cacheHeaders,on:app.eventLoopGroup.next())\n  precondition(installer._streamPayload(at:url,for:unchanged).status == .notModified,"Preserved conditional response")\n  let failedRequest=Request(application:app,method:.GET,url:"/failed",on:app.eventLoopGroup.next())\n  installer.viewModel.status = .sendingPayload\n  let failedResponse=installer._streamPayload(at:url,for:failedRequest)\n  try FileManager.default.removeItem(at:url)\n  do {_ = try await failedResponse.body.collect(on:failedRequest.eventLoop).get();preconditionFailure("Expected missing payload failure")} catch {}\n  try await Task.sleep(nanoseconds:10_000_000)\n  if case .broken=installer.viewModel.status {} else {preconditionFailure("Failed stream must report failure")}\n  let missing=Request(application:app,method:.GET,url:"/missing",on:app.eventLoopGroup.next())\n  precondition(installer._streamPayload(at:url.appendingPathComponent("missing"),for:missing).status == .internalServerError)\n  try await app.asyncShutdown()\n  print("Server payload progress checks passed: complete and resumed responses")\n }\n}\n'
source=header+s[a:b].replace('nonisolated private func','func',1)+'\n}\n'
source+=(repo/'Aether/Utilities/OperationProgressPublisher.swift').read_text()+'\n'+main
pins=json.loads((repo/'Aether.xcodeproj/project.xcworkspace/xcshareddata/swiftpm/Package.resolved').read_text())['pins']
version=next(p['state']['version'] for p in pins if p['identity']=='vapor')
package='// swift-tools-version: 5.9\nimport PackageDescription\nlet package = Package(name: "Checks", platforms: [.macOS(.v13)], dependencies: [.package(url: "https://github.com/vapor/vapor", exact: "'+version+'")], targets: [.executableTarget(name: "Checks", dependencies: [.product(name: "Vapor", package: "vapor")])])\n'
with tempfile.TemporaryDirectory(prefix='aether-server-progress-') as d:
 root=pathlib.Path(d);(root/'Sources/Checks').mkdir(parents=True)
 (root/'Package.swift').write_text(package)
 (root/'Sources/Checks/Checks.swift').write_text(source)
 subprocess.run(['swift','run','--package-path',str(root)],check=True)
